        // We need to ensure contract is not paused
        // Check paused slot (likely slot 1) and set to false if needed
        vm.store(TARGET, bytes32(uint256(1)), bytes32(uint256(0))); // Set paused = false

        // Now call destroyBlackFunds
        ITetherToken(TARGET).destroyBlackFunds(attacker);

        // Step 6: Call issue() to mint tokens
        // Issue 1 million tokens
        ITetherToken(TARGET).issue(1000000 * 10**6);

