        uint256 finalBalance = ITetherToken(TARGET).balanceOf(attacker);
        uint256 initialBalance = 1e18; // From setup
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
